import './App.css';
import { useState } from 'react';

function Opiniones() {
  const [comentario, setComentario] = useState('');
  const [rating, setRating] = useState(0);
  const [opinionesLista, setOpinionesLista] = useState([]);

  const enviarOpinion = (e) => {
    e.preventDefault();
    if (comentario && rating > 0) {
      setOpinionesLista([...opinionesLista, { comentario, rating }]);
      setComentario('');
      setRating(0);
    }
  };

  return (
    <>
      <header>
        <div className="logo-contenedor">
          <img src="/Logotipo.jpg" alt="Logo Taller Robledo" className="logo" />
          <div className="texto-logo">
            <span className="slogan">FABRICACIÓN DE VOLCOS</span>
            <span className="nombre">TALLER ROBLEDO</span>
          </div>
        </div>
        <nav>
          <ul className="menu">
            <li><a href="/">Inicio</a></li>
            <li><a href="/volcos">Volcos</a></li>
            <li><a href="/cotizacion">Cotización</a></li>
            <li><a href="/contacto">Contacto</a></li>
            <li><a href="/opiniones" className="active">Opiniones</a></li>
            <li><a href="/registro">Registro</a></li>
          </ul>
        </nav>
      </header>

      <main>
        <h1>Califique Nuestro Servicio</h1>

        <div className="rating">
          {[5, 4, 3, 2, 1].map((val) => (
            <span
              key={val}
              style={{ cursor: 'pointer', color: val <= rating ? '#f5c518' : '#ccc' }}
              onClick={() => setRating(val)}
            >
              ★
            </span>
          ))}
        </div>

        <textarea
          rows="4"
          placeholder="Escriba su opinión..."
          value={comentario}
          onChange={(e) => setComentario(e.target.value)}
        />

        <button onClick={enviarOpinion} className="btn-opinion">Enviar Opinión</button>

        <div id="opinionesLista">
          {opinionesLista.map((op, index) => (
            <div key={index} className="opinion-item">
              <p>{'★'.repeat(op.rating)}</p>
              <p>{op.comentario}</p>
            </div>
          ))}
        </div>
      </main>

      <footer className="footer">
        <div className="footer-left">
          <p>Taller Robledo | 📞 314 880 5733</p>
        </div>
        <div className="footer-right">
          <p>&copy; 2025 Todos los derechos reservados</p>
        </div>
      </footer>
    </>
  );
}

export default Opiniones;
